Q: How to dynamically update SEO meta tags in React using native DOM API without third-party libraries? A: <p>Yeah, you can definitely do this without external libraries. The key is just using <code>useEffect</code> to update the DOM directly and then wrapping it in a context for your site defaults.</p>
<p>Here's the basic approach:</p>
<pre><code>// hooks/useSEO.js
import { useEffect } from 'react';

export function useSEO({ title, description, canonical, robots, openGraph, twitter, jsonLd }) {
  useEffect(() =&gt; {
    document.title = title;

    // Helper to create/update meta tags
    const setMeta = (name, content, isProperty = false) =&gt; {
      let el = document.querySelector(
        isProperty ? `meta[property=&quot;${name}&quot;]` : `meta[name=&quot;${name}&quot;]`
      );
      if (!el) {
        el = document.createElement('meta');
        el.setAttribute(isProperty ? 'property' : 'name', name);
        document.head.appendChild(el);
      }
      el.content = content;
    };

    if (description) setMeta('description', description);

    // For robots, join the object into a string
    if (robots) {
      const robotsStr = Object.entries(robots)
        .filter(([, v]) =&gt; v !== false)
        .map(([k, v]) =&gt; (v === true ? k : `${k}:${v}`))
        .join(', ');
      if (robotsStr) setMeta('robots', robotsStr);
    }

    // OG tags
    if (openGraph) {
      Object.entries(openGraph).forEach(([key, value]) =&gt; {
        if (Array.isArray(value)) {
          value.forEach((item) =&gt; {
            Object.entries(item).forEach(([k, v]) =&gt; {
              setMeta(`og:${key}:${k}`, String(v), true);
            });
          });
        } else if (value) {
          setMeta(`og:${key}`, String(value), true);
        }
      });
    }

    // Twitter tags
    if (twitter) {
      Object.entries(twitter).forEach(([key, value]) =&gt; {
        if (value) setMeta(`twitter:${key}`, String(value));
      });
    }

    // Canonical
    if (canonical) {
      let link = document.querySelector('link[rel=&quot;canonical&quot;]');
      if (!link) {
        link = document.createElement('link');
        link.rel = 'canonical';
        document.head.appendChild(link);
      }
      link.href = canonical;
    }

    // JSON-LD (for breadcrumbs, etc)
    if (jsonLd) {
      let script = document.querySelector('script[type=&quot;application/ld+json&quot;]');
      if (!script) {
        script = document.createElement('script');
        script.type = 'application/ld+json';
        document.head.appendChild(script);
      }
      script.textContent = JSON.stringify(jsonLd);
    }
  }, [title, description, canonical, robots, openGraph, twitter, jsonLd]);
}
</code></pre>
<p>Then create a context for your defaults:</p>
<pre><code>// context/SEOContext.js
import { createContext, useContext } from 'react';

const SEOContext = createContext({});

export function SEOProvider({ children, defaults }) {
  return &lt;SEOContext.Provider value={defaults}&gt;{children}&lt;/SEOContext.Provider&gt;;
}

export function useSEODefaults() {
  return useContext(SEOContext);
}
</code></pre>
<p>And a simple component that merges everything:</p>
<pre><code>// components/SEO.jsx
import { useSEO } from '../hooks/useSEO';
import { useSEODefaults } from '../context/SEOContext';

export function SEO({ title, description, canonical, robots, openGraph, twitter, jsonLd }) {
  const defaults = useSEODefaults();

  const finalTitle = title
    ? defaults.titleTemplate?.replace('%s', title) || title
    : defaults.defaultTitle;

  useSEO({
    title: finalTitle,
    description: description || defaults.description,
    canonical,
    robots: { ...defaults.robots, ...robots },
    openGraph: { ...defaults.openGraph, ...openGraph },
    twitter: { ...defaults.twitter, ...twitter },
    jsonLd,
  });

  return null;
}
</code></pre>
<p>Set it up in your main:</p>
<pre><code>&lt;SEOProvider
  defaults={{
    titleTemplate: '%s | My Site',
    defaultTitle: 'My Site',
    description: 'Default description',
    robots: { index: true, follow: true },
    openGraph: { type: 'website', siteName: 'My Site' },
    twitter: { site: '@mysite' },
  }}
&gt;
  &lt;App /&gt;
&lt;/SEOProvider&gt;
</code></pre>
<p>Then on each page just do:</p>
<pre><code>&lt;SEO
  title={post.title}
  description={post.excerpt}
  canonical={`https://example.com/blog/${post.slug}`}
  openGraph={{
    type: 'article',
    images: [{ url: post.coverImage, width: 1200, height: 630 }],
  }}
  jsonLd={{
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: 'https://example.com' },
      { '@type': 'ListItem', position: 2, name: 'Blog', item: 'https://example.com/blog' },
      { '@type': 'ListItem', position: 3, name: post.title },
    ],
  }}
/&gt;
</code></pre>
<p>That handles all your requirements—site-wide defaults, per-page overrides, robots directives, OG tags, and JSON-LD. The robots object is type-safe too, so no more typos.</p>
<p>Only gotcha is if you're doing SSR later (like migrating to Next.js), you'd need to wrap the hook to skip it on the server side, but for Vite it should just work.</p>
